-module(bright_hub_view).
-export([render/0,login/0]).
head(Title,Script) -> [<<"<!doctype html><html lang='en'><head><meta charset='utf-8'><meta name='viewport' content='width=device-width,initial-scale=1'><title>">>,Title,
 <<" &middot; Bright Studio</title><link rel='stylesheet' href='/studio/hub.css'><script defer src='">>,Script,<<"'></script>">>,<<"</head><body><a class='skip' href='#main'>Skip to content</a>">>,development_notice()].
development_notice()->case os:getenv("BRIGHT_SQLITE_DEVELOPMENT") of
    "true"-><<"<p class='development-notice' role='note'>Development demo: saved data can reset when the server restarts. Keep a copy of anything you need.</p>">>;
    _-><<>>
end.
login() -> [head(<<"Sign in">>,<<"/studio/login.js">>),
 <<"<main id='main' class='login'><p class='eyebrow'>Bright Studio</p><h1>Sign in</h1><p>Open your learning workspace.</p><form id='login-form'><label>Email<input name='email' type='email' autocomplete='username' required maxlength='254'></label><label>Password<input name='password' type='password' autocomplete='current-password' required maxlength='1024'></label><button>Sign in</button><p id='status' role='status' aria-live='polite'></p></form>">>,case bright_access:enabled() of true-> <<"<p><a href='/studio/recover/'>Forgot password?</a></p>">>;false->[] end,<<"</main></body></html>">>].
render() -> [head(<<"Learning Hub">>,<<"/studio/hub/hub.js">>),
 <<"<div class='layout'><aside id='navigation'><button id='navigation-close' class='secondary mobile-only' type='button'>Close navigation</button><a class='brand' href='/studio/hub/'>bright studio</a><nav aria-label='Primary'><a href='/studio/hub/'>Overview</a><a href='/studio/hub/library/'>Library</a><a id='evidence-nav' href='/studio/hub/evidence/' hidden>Evidence</a><a id='study-nav' href='/studio/hub/study/' hidden>Study</a><a id='focus-nav' href='/studio/hub/focus/' hidden>Focus</a><a id='offline-nav' href='/studio/hub/offline/' hidden>Offline</a><a id='audio-nav' href='/studio/hub/audio/' hidden>Audio &amp; capture</a><a id='assistant-nav' href='/studio/hub/assistant/' hidden>Assistant</a><a id='documents-nav' href='/studio/hub/documents/' hidden>Documents</a><a class='workspace-nav' href='/studio/hub/projects/' hidden>Projects</a><a class='workspace-nav' href='/studio/hub/tasks/' hidden>Tasks</a><a class='workspace-nav' href='/studio/hub/planner/' hidden>Planner</a><a class='workspace-nav' href='/studio/hub/account/' hidden>Account</a><a id='access-nav' href='/studio/hub/access/' hidden>Access &amp; members</a></nav></aside><div class='content'><header><button id='navigation-open' class='secondary mobile-only' type='button' aria-controls='navigation' aria-expanded='false'>Menu</button><label class='project-label'>Project<select id='project' aria-label='Project'></select></label><span id='account'></span><button id='logout' class='secondary'>Sign out</button></header><main id='main' tabindex='-1'><div id='page-intro'><p class='eyebrow'>Your learning workspace</p><h1 id='heading'>Library</h1><p id='description'>Keep the sources that matter, and return to them when you are ready.</p><p class='notice' id='library-notice'>Save source metadata now, or add a file to read it here.</p><p id='status' role='status' aria-live='polite'>Loading projects&hellip;</p></div><section id='library' hidden><article id='continue-reading' class='continue' hidden><div><p class='eyebrow'>Ready to read</p><h2 id='continue-title'></h2><p id='continue-detail'></p></div><a id='continue-link' class='button-link'>Open reader</a></article><div class='section-title'><h2 id='sources-heading'>Your sources</h2></div><div class='toolbar'><label>Search sources<input id='search' type='search'></label><button id='add'>Add Source</button></div><p id='empty' hidden>No sources yet. Add your first source to start your library.</p><div id='sources' class='grid'></div><section id='overview-study' hidden><h2>Practice a saved idea</h2><div class='continue'><div><h3 id='overview-study-title'></h3><p id='overview-study-detail'></p></div><a id='overview-study-link' class='button-link'>Study</a></div></section></section><section id='reader' hidden><div class='activity-bar'><div class='source-context'><a href='/studio/hub/library/'>Back to Library</a><span id='reader-context-title'></span><small id='reader-context-revision'></small></div><div class='activity-actions'><button id='reading-mode' class='secondary' type='button' aria-pressed='false'>Reading mode</button><button id='reader-fullscreen' class='secondary' type='button' aria-pressed='false'>Full screen</button></div></div><h2 id='source-title'></h2><p id='source-kind'></p><a id='source-url' rel='noopener noreferrer' target='_blank' hidden>Open original link</a><p class='notice' id='metadata-only'>Reader placeholder. Only source metadata is saved; content has not been extracted.</p><section id='reading' hidden aria-label='Reading'><details id='reader-tools'><summary>Source options</summary><div class='toolbar'><label>Revision<select id='revision' aria-label='Revision'></select></label><a id='download' href='#'>Download original</a><button id='upload-revision' type='button'>Upload a revision</button></div></details><p id='reading-status' role='status' aria-live='polite'></p><button id='retry' type='button' hidden>Retry extraction</button><article id='reading-text' aria-label='Source text'></article><div class='reader-actions'><a id='study-source' hidden>Study this revision</a><a id='focus-source' hidden>Focus on this revision</a><button id='capture-selection' class='secondary' type='button' disabled>Capture selected text</button><button id='notes-open' class='secondary' type='button' aria-controls='evidence-panel' aria-expanded='false' hidden>Notes</button></div></section><section id='evidence-panel' hidden aria-label='Evidence and notes'><div class='notes-heading'><h2>Evidence and notes</h2><button id='notes-close' class='secondary' type='button'>Close notes</button></div><p>Select text in the Reader, then capture it. Or enter an exact quote below to find its location using the keyboard.</p><label>Find a quote<textarea id='find-quote' rows='2' maxlength='2048'></textarea></label><button id='find-selection' type='button' disabled class='secondary'>Find quote</button><p id='evidence-status' role='status'></p><div id='evidence-list'></div></section><button id='first-upload' type='button' hidden>Upload a file</button></section><section id='boards-page' hidden aria-label='Project evidence boards'><h2>Project boards</h2><form id='board-form'><label>Board title<input id='board-title' required maxlength='120'></label><button>Create board</button></form><p id='board-status' role='status'>Loading boards&hellip;</p><div id='board-list' class='grid'></div><section id='board-detail' hidden><h3 id='board-heading'></h3><div id='board-items'></div></section></section><section id='study-page' hidden aria-label='Study'><p>Practice missing-word recall from your saved sources. Each lesson covers up to six passages of 80 words (2,000 characters each). Answer each question, then save a reflection to finish.</p><p id='study-status' role='status' aria-live='polite'></p><div id='study-picker' class='grid'></div><div id='study-passes' class='grid'></div><section id='study-lesson' hidden><div class='activity-bar'><div class='source-context'><a id='study-origin'>Open pinned source revision</a><span id='study-context-title'></span><small id='study-context-revision'></small></div><div class='activity-actions'><button id='study-mode' class='secondary' type='button' aria-pressed='false'>Study mode</button><button id='study-fullscreen' class='secondary' type='button' aria-pressed='false'>Full screen</button></div></div><p class='eyebrow'>One idea at a time</p><h2 id='study-title'></h2><p id='study-progress'></p><progress id='lesson-progress' aria-label='Lesson progress' max='1' value='0'></progress><h3 id='study-step-title'>Recall the idea</h3><form id='study-form'><label id='study-prompt' for='study-answer'></label><details id='study-reference'><summary>Read the passage</summary><p id='study-text'></p></details><textarea id='study-answer' placeholder='Your answer&hellip;' required maxlength='2000' rows='4'></textarea><button id='study-submit'>Check answer</button></form><p id='study-feedback' role='status' aria-live='polite'></p><blockquote id='study-summary' hidden></blockquote><button id='study-back' type='button' class='secondary'>Back to lessons</button></section><button id='study-reload' class='secondary' type='button'>Refresh study</button></section><section id='focus-page' hidden aria-label='Focus'><p id='focus-status' role='status' aria-live='polite'></p><div id='focus-home'><button id='focus-reload' class='secondary' type='button'>Refresh sessions</button><div id='focus-current' hidden></div><form id='focus-start'><h2>Make room for one thing</h2><label>Learning work<select id='focus-target' required></select></label><label>Session minutes<input id='focus-minutes' type='number' min='1' max='120' step='1' value='25' required></label><button id='focus-start-button'>Start focus</button></form><h2>Recent sessions</h2><div id='focus-list' class='grid'></div></div><section id='focus-session' hidden aria-labelledby='focus-title'><div class='activity-bar'><span id='focus-context'></span><div class='activity-actions'><button id='focus-mode' class='secondary' type='button' aria-pressed='false'>Focus mode</button><button id='focus-fullscreen' class='secondary' type='button' aria-pressed='false'>Full screen</button></div></div><div class='focus-body'><p class='eyebrow'>One thing at a time</p><h2 id='focus-title'></h2><p id='focus-timer' aria-label='Remaining focus time'></p><p id='focus-state'></p><p id='focus-hint'></p><a id='focus-origin'>Open linked work</a><div class='focus-controls'><button id='focus-pause' type='button'>Pause session</button><button id='focus-resume' type='button' hidden>Resume session</button><button id='focus-sync' class='secondary' type='button'>Load saved session</button></div><p id='focus-save-status' role='status' aria-live='polite'></p><details id='focus-checkpoint-box' class='focus-box'><summary>Add a checkpoint</summary><form id='focus-checkpoint'><h3>Save a checkpoint</h3><label>Checkpoint note<textarea id='focus-note' required minlength='10' maxlength='2000' rows='3' placeholder='What did you work on or notice?'></textarea></label><label id='focus-evidence-label' hidden>Link evidence (optional)<select id='focus-evidence'><option value=''>No evidence link</option></select></label><button id='focus-checkpoint-save'>Save checkpoint</button></form></details><div id='focus-checkpoints'></div><details id='focus-complete-box' class='focus-box'><summary>Session reflection</summary><form id='focus-complete'><h3>Take one idea with you</h3><p id='focus-gate'></p><label>Session reflection<textarea id='focus-summary' required minlength='20' maxlength='2000' rows='3'></textarea></label><button id='focus-finish'>Complete session</button></form></details><blockquote id='focus-completed-summary' hidden></blockquote><div class='focus-bottom'><button id='focus-back' class='secondary' type='button'>Back to sessions</button><button id='focus-cancel' class='secondary' type='button'>Cancel session</button></div></div></section></section><section id='offline-page' hidden aria-label='Offline copies'><p id='offline-status' role='status' aria-live='polite'></p><p>Copies stay on this device until you remove them. Signing out clears them. Remote revocation takes effect when you reconnect; server sync always checks access.</p><form id='offline-create'><fieldset id='offline-targets'><legend>Sources and documents to keep (up to five of each)</legend></fieldset><label><input id='offline-consent' type='checkbox' required> Keep these private copies on this device for up to seven days.</label><button id='offline-download'>Make offline copy</button></form><button id='offline-reload' type='button' class='secondary'>Reload copies</button><button id='offline-sync' type='button'>Sync saved drafts</button><button id='offline-clear' type='button' class='secondary'>Remove all local copies</button><div id='offline-copies'></div><section id='offline-editor' hidden><h2 id='offline-document-title'></h2><label>Document title<input id='offline-title' maxlength='200' required></label><div id='offline-blocks'></div><button id='offline-add' class='secondary' type='button'>Add text block</button><button id='offline-save-draft' type='button'>Save draft on this device</button><p id='offline-draft-status' role='status'></p></section></section><section id='media-page' hidden aria-label='Audio and capture'><p id='media-status' role='status' aria-live='polite'></p><p id='media-availability'></p><form id='media-upload'><label>Capture title<input id='media-title' required maxlength='200'></label><label>Audio or page<input id='media-file' type='file' accept='.wav,.webm,.png,.jpg,.jpeg,audio/wav,audio/webm,image/png,image/jpeg' required></label><button id='media-save'>Save private capture</button></form><details><summary>Record a spoken idea</summary><p>Recording starts only after you allow microphone access. Stop within one minute, then choose a title and save it.</p><button id='media-record' class='secondary' type='button'>Start recording</button><button id='media-stop' class='secondary' type='button' disabled>Stop recording</button><p id='media-record-status' role='status'></p><button id='media-save-recording' class='secondary' type='button' disabled>Save recording</button><button id='media-discard-recording' class='secondary' type='button' disabled>Discard recording</button></details><button id='media-reload' class='secondary' type='button'>Reload captures</button><div id='media-jobs' class='grid'></div></section><section id='assistant-page' hidden aria-label='Assistant'><p id='assistant-status' role='status' aria-live='polite'></p><form id='assistant-form'><label>Activity<select id='assistant-mode'><option value='explain'>Explain</option><option value='compare'>Compare</option><option value='feedback'>Review my answer</option></select></label><fieldset id='assistant-evidence'><legend>Evidence (choose up to three passages)</legend></fieldset><label>Your question or answer<textarea id='assistant-prompt' required maxlength='2000' rows='4'></textarea></label><label>Answer style<select id='assistant-engine'><option value='evidence'>Evidence guide</option><option id='assistant-generated' value='generated'>Generated answer</option></select></label><p id='assistant-availability'></p><button id='assistant-ask'>Ask</button></form><button id='assistant-reload' type='button' class='secondary'>Reload saved answers</button><div id='assistant-results'></div></section><section id='documents-page' hidden aria-label='Documents'><p id='documents-status' role='status' aria-live='polite'></p><section id='documents-home'><form id='document-create'><label>Document title<input id='document-new-title' required maxlength='200'></label><button id='document-create-button'>New document</button></form><button id='documents-reload' class='secondary' type='button'>Reload documents</button><div id='documents-list' class='grid'></div></section><section id='document-editor' hidden><div class='activity-bar'><button id='document-back' class='secondary' type='button'>Back to documents</button><div class='activity-actions'><button id='document-mode' class='secondary' type='button' aria-pressed='false'>Writing mode</button><button id='document-fullscreen' class='secondary' type='button' aria-pressed='false'>Full screen</button></div></div><label>Document title<input id='document-title' required maxlength='200'></label><p id='document-revision'></p><details><summary>Saved revisions</summary><label>Document revision<select id='document-history'></select></label><button id='document-view-version' class='secondary' type='button'>View revision</button><button id='document-latest' class='secondary' type='button'>Load latest saved revision</button></details><div id='document-blocks'></div><div class='actions'><button id='document-add' class='secondary' type='button'>Add text block</button><label>Cited evidence<select id='document-evidence'></select></label><button id='document-cite' class='secondary' type='button'>Add cited block</button></div><div class='actions'><button id='document-save' type='button'>Save revision</button><a id='document-export'>Export saved Markdown</a></div><p id='document-save-status' role='status' aria-live='polite'></p><details id='document-conflict-panel' hidden><summary>Latest saved revision for comparison</summary><pre id='document-conflict'></pre></details><button id='document-rebase' class='secondary' type='button' hidden>Keep my draft and use latest version</button></section></section><section id='workspace-page' hidden aria-label='Workspace'><p id='workspace-status' role='status' aria-live='polite'>Loading saved data&hellip;</p><button id='workspace-retry' class='secondary' type='button'>Reload saved data</button><section id='projects-page' hidden><h2>Your projects</h2><form id='project-create'><label>New project name<input id='project-name' required maxlength='200'></label><button>Create project</button></form><div id='project-list' class='grid'></div></section><section id='tasks-page' hidden><div class='toolbar'><button id='task-add' type='button'>Add task</button><label>Task status<select id='task-filter'><option value='all'>All tasks</option><option value='open'>Open tasks</option><option value='done'>Completed tasks</option></select></label><label>Search tasks<input id='task-search' type='search'></label></div><div id='planner-controls' hidden><label>Planner date<input id='planner-date' type='date' min='1900-01-01' max='2100-12-31' required></label><button id='planner-today' class='secondary' type='button'>Today</button><p id='planner-zone'></p></div><p id='task-totals'></p><p id='task-empty' hidden>No tasks yet. Add a task to start planning.</p><div id='task-list' class='grid'></div></section><section id='account-page' hidden><h2>Account settings</h2><form id='account-form'><p id='account-email'></p><label>Display name<input id='account-name' maxlength='100'></label><label>Timezone<select id='account-zone' aria-label='Timezone'></select></label><button>Save account settings</button><button id='account-latest' type='button' class='secondary' hidden>Load latest version and keep my draft</button><p id='account-status' role='status' aria-live='polite'></p></form><h2>Change password</h2><p>Changing your password signs out every session. Use at least 12 characters, up to 1,024 UTF-8 bytes. Forgotten-password recovery requires your workspace administrator.</p><form id='password-form'><label>Current password<input id='password-current' type='password' autocomplete='current-password' required maxlength='1024'></label><label>New password<input id='password-new' type='password' autocomplete='new-password' required minlength='12' maxlength='1024'></label><label>Confirm new password<input id='password-confirm' type='password' autocomplete='new-password' required minlength='12' maxlength='1024'></label><button>Change password and sign out</button><p id='password-status' role='status' aria-live='polite'></p></form></section></section></main></div></div><dialog id='evidence-dialog' aria-labelledby='evidence-dialog-title'><form id='evidence-form'><h2 id='evidence-dialog-title'>Save evidence</h2><blockquote id='selected-quote'></blockquote><label>Evidence note<textarea id='evidence-note' rows='5' maxlength='4000'></textarea></label><p id='evidence-form-status' role='status'></p><div class='actions'><button id='evidence-cancel' type='button' class='secondary'>Cancel</button><button id='evidence-save'>Save evidence</button></div></form></dialog><dialog id='dialog' aria-labelledby='dialog-title'><form id='source-form'><h2 id='dialog-title'>Add Source</h2><p id='dialog-description'>Save a source to this project.</p><div id='metadata-fields'><label>Title<input name='title' required maxlength='200'></label><label>Type<select name='kind'><option value='note'>Note</option><option value='article'>Article</option><option value='book'>Book</option><option value='link'>Link</option></select></label><label>Original URL (optional)<input name='url' type='url' maxlength='2048' placeholder='https://'></label></div><label id='file-label' hidden>Source file (TXT, PDF or EPUB; up to 4 MiB)<input id='file' name='file' type='file' accept='.txt,.pdf,.epub,text/plain,application/pdf,application/epub+zip'></label><p id='form-status' role='status' aria-live='polite'></p><div class='actions'><button id='cancel' type='button' class='secondary'>Cancel</button><button id='save'>Save source</button></div></form></dialog><dialog id='project-dialog' aria-labelledby='project-dialog-title'><form id='project-edit'><h2 id='project-dialog-title'>Rename project</h2><label>Project name<input id='project-edit-name' required maxlength='200'></label><p id='project-edit-status' role='status' aria-live='polite'></p><button id='project-latest' type='button' class='secondary' hidden>Load latest version and keep my draft</button><div class='actions'><button id='project-cancel' type='button' class='secondary'>Cancel</button><button id='project-save'>Save project</button></div></form></dialog><dialog id='task-dialog' aria-labelledby='task-dialog-title'><form id='task-form'><h2 id='task-dialog-title'>Add task</h2><label>Task title<input id='task-title' required maxlength='200'></label><label>Task project<select id='task-project' aria-label='Task project'></select></label><label>Task state<select id='task-state'><option value='todo'>To do</option><option value='doing'>In progress</option><option value='done'>Completed</option></select></label><label>Scheduled date<input id='task-scheduled' type='date' min='1900-01-01' max='2100-12-31'></label><label>Due date<input id='task-due' type='date' min='1900-01-01' max='2100-12-31'></label><label>Priority<select id='task-priority'><option value='1'>High</option><option value='2'>Normal</option><option value='3'>Low</option></select></label><label>Estimated minutes<input id='task-minutes' type='number' required min='5' max='480' step='1' value='25'></label><label>Task notes<textarea id='task-note' rows='3' maxlength='2000'></textarea></label><p id='task-form-status' role='status' aria-live='polite'></p><button id='task-latest' type='button' class='secondary' hidden>Load latest version and keep my draft</button><div class='actions'><button id='task-cancel' type='button' class='secondary'>Cancel</button><button id='task-save'>Save task</button></div></form></dialog></body></html>">>].
